package com.amilingo.platform.module.patent.service;
import com.amilingo.platform.module.patent.dto.PatentOperationsDTO.*;import com.amilingo.platform.module.patent.entity.*;import com.amilingo.platform.module.patent.repository.*;
import org.junit.jupiter.api.*;import org.mockito.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class PatentOperationsServiceTest{
 @Mock PatentRepository patentRepo;@Mock PatentDocumentRepository documentRepo;@Mock PatentClaimRepository claimRepo;@Mock PatentOfficeActionRepository actionRepo;@Mock PatentDeadlineRepository deadlineRepo;@Mock PatentFeeRepository feeRepo;
 AutoCloseable mocks;PatentOperationsService service;@BeforeEach void setup(){mocks=MockitoAnnotations.openMocks(this);service=new PatentOperationsService(patentRepo,documentRepo,claimRepo,actionRepo,deadlineRepo,feeRepo);when(patentRepo.findById(1L)).thenReturn(Optional.of(Patent.builder().id(1L).userId(7L).build()));}@AfterEach void close()throws Exception{mocks.close();}
 @Test void documentMetadataIsStored(){when(documentRepo.save(any())).thenAnswer(i->i.getArgument(0));PatentDocument d=service.addDocument(1L,new DocumentRequest(7L,null,"CLAIMS","claims.pdf","application/pdf",100L,"k1",null,"hash",1));assertEquals("ACTIVE",d.getStatus());assertEquals("k1",d.getStorageKey());}
 @Test void dependentClaimRequiresExistingParent(){when(claimRepo.existsByPatentIdAndClaimNoAndCurrentVersionTrue(1L,1)).thenReturn(false);ClaimRequest r=new ClaimRequest(7L,2,"DEPENDENT",1,"内容",null,null);assertThrows(IllegalArgumentException.class,()->service.createClaim(1L,r));}
 @Test void officeActionCreatesDeadline(){when(actionRepo.findFirstByPatentIdOrderByRoundNoDesc(1L)).thenReturn(Optional.empty());when(actionRepo.save(any())).thenAnswer(i->{PatentOfficeAction a=i.getArgument(0);a.setId(10L);return a;});when(deadlineRepo.save(any())).thenAnswer(i->i.getArgument(0));PatentOfficeAction a=service.createOfficeAction(1L,new OfficeActionRequest(7L,"OFFICE_ACTION",LocalDate.of(2026,1,1),LocalDate.of(2026,2,1),"意见",8L,List.of()));assertEquals(1,a.getRoundNo());verify(deadlineRepo).save(argThat(d->d.getRelatedRecordId().equals(10L)&&"OFFICE_ACTION_RESPONSE".equals(d.getType())));}
 @Test void responseCompletesLinkedDeadline(){PatentOfficeAction a=PatentOfficeAction.builder().id(10L).patentId(1L).status("PENDING").build();PatentDeadline d=PatentDeadline.builder().id(20L).patentId(1L).relatedRecordId(10L).type("OFFICE_ACTION_RESPONSE").status("PENDING").build();when(actionRepo.findById(10L)).thenReturn(Optional.of(a));when(actionRepo.save(any())).thenAnswer(i->i.getArgument(0));when(deadlineRepo.findByPatentIdOrderByDueDateAsc(1L)).thenReturn(List.of(d));service.respondOfficeAction(10L,new OfficeActionResponseRequest(7L,"答复",null,List.of()));assertEquals("RESPONDED",a.getStatus());assertEquals("COMPLETED",d.getStatus());}
 @Test void feeReductionCannotExceedAmount(){FeeRequest r=new FeeRequest(7L,"APPLICATION",new BigDecimal("100"),"CNY",new BigDecimal("101"),LocalDate.now(),null);assertThrows(IllegalArgumentException.class,()->service.createFee(1L,r));}
 @Test void feeSummaryCalculatesNetPaidAndUnpaid(){PatentFee paid=PatentFee.builder().patentId(1L).type("APPLICATION").amount(new BigDecimal("100")).reductionAmount(new BigDecimal("20")).currency("CNY").status("PAID").build();PatentFee unpaid=PatentFee.builder().patentId(1L).type("ANNUITY").amount(new BigDecimal("200")).reductionAmount(BigDecimal.ZERO).currency("CNY").status("UNPAID").build();when(feeRepo.findByPatentIdOrderByDueDateAscIdAsc(1L)).thenReturn(List.of(paid,unpaid));FeeSummary s=service.feeSummary(1L,7L);assertEquals(new BigDecimal("280"),s.totalPayable());assertEquals(new BigDecimal("80"),s.totalPaid());assertEquals(new BigDecimal("200"),s.totalUnpaid());}
}
